import { settleCapturedPayment, settleDispute, settleRefund } from "../_shared/settle.ts";

const encoder = new TextEncoder();
const HEX_SIGNATURE = /^[0-9a-f]{64}$/i;
const PAYMENT_ID = /^pay_[A-Za-z0-9]{6,32}$/;
const ORDER_ID = /^order_[A-Za-z0-9]{6,32}$/;
const DISPUTE_ID = /^disp_[A-Za-z0-9]{6,32}$/;
const DISPUTE_EVENTS = new Set([
  "payment.dispute.created",
  "payment.dispute.under_review",
  "payment.dispute.action_required",
  "payment.dispute.won",
  "payment.dispute.lost",
  "payment.dispute.closed",
]);

function response(status: number, body?: Record<string, string>): Response {
  return new Response(body ? JSON.stringify(body) : null, {
    status,
    headers: body ? { "Content-Type": "application/json" } : undefined,
  });
}

function requiredSecret(name: string): string {
  const value = Deno.env.get(name);
  if (!value) throw new Error(`Missing ${name} Edge Function secret`);
  return value;
}

async function hmacSha256Hex(secret: string, rawBody: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const digest = await crypto.subtle.sign("HMAC", key, encoder.encode(rawBody));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

// Web Crypto has no timingSafeEqual. Compare fixed-width, decoded SHA-256
// bytes without returning early. Invalidly-shaped signatures are rejected
// before this function, so both arrays are always 32 bytes.
function timingSafeEqualHex(expected: string, received: string): boolean {
  let difference = 0;
  for (let i = 0; i < expected.length; i += 2) {
    difference |= Number.parseInt(expected.slice(i, i + 2), 16)
      ^ Number.parseInt(received.slice(i, i + 2), 16);
  }
  return difference === 0;
}

async function signatureIsValid(rawBody: string, signature: string): Promise<boolean> {
  if (!HEX_SIGNATURE.test(signature)) return false;

  const currentExpected = await hmacSha256Hex(requiredSecret("RAZORPAY_WEBHOOK_SECRET"), rawBody);
  let valid = timingSafeEqualHex(currentExpected, signature.toLowerCase());

  // Razorpay retries old deliveries after a Dashboard secret rotation using
  // the secret that signed the original delivery. Keep the previous secret
  // only for the documented retry window, then remove it.
  const previousSecret = Deno.env.get("RAZORPAY_WEBHOOK_PREVIOUS_SECRET");
  if (previousSecret) {
    const previousExpected = await hmacSha256Hex(previousSecret, rawBody);
    valid = timingSafeEqualHex(previousExpected, signature.toLowerCase()) || valid;
  }
  return valid;
}

type RazorpayPayment = {
  id?: string;
  order_id?: string;
  amount?: number;
  status?: string;
  captured?: boolean;
};

type RazorpayWebhook = {
  event?: string;
  payload?: {
    payment?: { entity?: RazorpayPayment };
    refund?: { entity?: { id?: string; payment_id?: string } };
    dispute?: { entity?: { id?: string; payment_id?: string; status?: string } };
  };
};

type ValidatedPayment = { id: string; orderId: string; amountPaise: number };

// Narrows the untrusted webhook entity to the fields settlement relies on.
// Anything missing or malformed is rejected here, before settlement is reached.
function parseCapturedPayment(
  entity: RazorpayPayment | undefined
): ({ ok: true } & ValidatedPayment) | { ok: false; problem: string } {
  if (!entity || typeof entity !== "object") return { ok: false, problem: "missing payment entity" };

  const { id, order_id: orderId, amount, status, captured } = entity;
  if (typeof id !== "string" || !PAYMENT_ID.test(id)) return { ok: false, problem: "missing or malformed payment id" };
  if (typeof orderId !== "string" || !ORDER_ID.test(orderId)) return { ok: false, problem: "missing or malformed order id" };
  if (typeof amount !== "number" || !Number.isSafeInteger(amount) || amount <= 0) {
    return { ok: false, problem: "missing or invalid amount" };
  }
  if (status !== "captured" && captured !== true) return { ok: false, problem: "payment not captured" };

  return { ok: true, id, orderId, amountPaise: amount };
}

Deno.serve(async (request: Request) => {
  if (request.method !== "POST") return response(405, { error: "Method not allowed" });

  const signature = request.headers.get("x-razorpay-signature");
  const eventId = request.headers.get("x-razorpay-event-id");
  if (!signature || !eventId) return response(400, { error: "Missing Razorpay webhook headers" });

  // This must be the first and only body read. Do not use request.json(),
  // JSON.stringify(), trimming, or any other transformation before HMAC.
  const rawBody = await request.text();
  try {
    if (!(await signatureIsValid(rawBody, signature))) {
      console.warn("razorpay-webhook: invalid signature", { eventId });
      return response(401, { error: "Invalid signature" });
    }
  } catch (error) {
    console.error("razorpay-webhook: signature configuration failure", error);
    return response(503, { error: "Webhook verification unavailable" });
  }

  let event: RazorpayWebhook;
  try {
    event = JSON.parse(rawBody) as RazorpayWebhook;
  } catch {
    return response(400, { error: "Invalid JSON" });
  }

  // refund.processed: cancels the referrer's credit if it is still in its hold.
  // Enable this event in the Razorpay Dashboard webhook alongside payment.captured.
  if (event.event === "refund.processed") {
    const refundPaymentId = event.payload?.refund?.entity?.payment_id ?? event.payload?.payment?.entity?.id;
    if (!refundPaymentId) {
      console.error("razorpay-webhook: malformed refund.processed payload", { eventId });
      return response(400, { error: "Invalid refund event" });
    }
    try {
      const refund = await settleRefund({ razorpayPaymentId: refundPaymentId });
      if (!refund.ok) return response(500, { error: "Unable to process webhook" }); // Razorpay retries
      console.log("razorpay-webhook: refund processed", { eventId, paymentId: refundPaymentId, outcome: refund.outcome });
      return response(204);
    } catch (error) {
      console.error("razorpay-webhook: refund error", { eventId, error: String(error) });
      return response(500, { error: "Unable to process webhook" });
    }
  }

  // payment.dispute.*: a chargeback suspends access while open, restores it if
  // won and reverses the purchase if lost. Enable these events in the Razorpay
  // Dashboard webhook. The dispute is re-fetched from Razorpay (settleDispute).
  if (event.event && DISPUTE_EVENTS.has(event.event)) {
    const disputeId = event.payload?.dispute?.entity?.id;
    if (typeof disputeId !== "string" || !DISPUTE_ID.test(disputeId)) {
      console.error("razorpay-webhook: malformed dispute payload", { eventId, event: event.event });
      return response(400, { error: "Invalid dispute event" });
    }
    try {
      const dispute = await settleDispute({ disputeId });
      if (!dispute.ok) return response(500, { error: "Unable to process webhook" }); // Razorpay retries
      console.log("razorpay-webhook: dispute processed", { eventId, disputeId, event: event.event, outcome: dispute.outcome });
      return response(204);
    } catch (error) {
      console.error("razorpay-webhook: dispute error", { eventId, error: String(error) });
      return response(500, { error: "Unable to process webhook" });
    }
  }

  // Acknowledge unrelated, authentic events. Everything except payment.captured,
  // refund.processed and payment.dispute.* is ignored, so out-of-order delivery is harmless.
  if (event.event !== "payment.captured") return response(204);

  const payment = parseCapturedPayment(event.payload?.payment?.entity);
  if (!payment.ok) {
    console.error("razorpay-webhook: malformed payment.captured payload", { eventId, problem: payment.problem });
    return response(400, { error: `Invalid payment event: ${payment.problem}` });
  }

  // Same settlement path as verify-payment: re-fetch the payment from Razorpay,
  // check captured / order / currency / amount against our order row, then the
  // atomic idempotent grant. Safe for Razorpay retries and for a concurrent
  // app-side verify-payment request.
  let result;
  try {
    result = await settleCapturedPayment({
      eventId,
      razorpayOrderId: payment.orderId,
      razorpayPaymentId: payment.id,
    });
  } catch (error) {
    console.error("razorpay-webhook: settlement error", { eventId, error: String(error) });
    return response(500, { error: "Unable to process webhook" }); // Razorpay retries
  }

  if (!result.ok) {
    console.error("razorpay-webhook: not settled", { eventId, paymentId: payment.id, reason: result.reason });
    // Permanent rejections (unknown order, mismatch) are acknowledged so Razorpay
    // stops retrying; they are logged for manual review. Transient failures
    // (5xx-class, not-yet-captured) return non-2xx so Razorpay retries.
    if (result.status === 404 || result.status === 400) return response(204);
    return response(500, { error: "Unable to process webhook" });
  }

  console.log("razorpay-webhook: processed", { eventId, paymentId: payment.id });
  return response(204);
});

// One settlement path for BOTH verify-payment (client callback / recovery) and
// razorpay-webhook (payment.captured). Nothing here trusts the caller: every
// fact is re-fetched from Razorpay or read from our own database, and the
// grant itself happens inside settle_razorpay_payment() (service_role only,
// row-locked, idempotent on razorpay_payment_id). That one transaction also
// debits the wallet amount stored on the order and creates the referrer's
// pending credit, so a payment that never captures never moves any money in
// the wallet.
import { supabaseAdmin } from "./supabaseAdmin.ts";
import { fetchDispute, fetchPayment, fetchRazorpayOrder } from "./razorpay.ts";

export type SettleResult =
  | { ok: true; orderId: string; amountRupees: number }
  | { ok: false; status: number; reason: string };

export async function settleCapturedPayment(params: {
  eventId: string;
  razorpayOrderId: string;
  razorpayPaymentId: string;
}): Promise<SettleResult> {
  const { eventId, razorpayOrderId, razorpayPaymentId } = params;

  // 1. Our own order row (it stores product_id, amount, razorpay_order_id together
  //    and is immutable after insert).
  const { data: order, error: orderErr } = await supabaseAdmin
    .from("orders")
    .select("id, user_id, product_id, amount, status, razorpay_order_id")
    .eq("razorpay_order_id", razorpayOrderId)
    .maybeSingle();
  if (orderErr) return { ok: false, status: 500, reason: "order lookup failed" };
  if (!order) return { ok: false, status: 404, reason: "order not found" };

  const expectedPaise = Math.round(Number(order.amount) * 100);
  if (!Number.isSafeInteger(expectedPaise) || expectedPaise <= 0) {
    return { ok: false, status: 500, reason: "invalid order amount" };
  }

  // 2. The payment, straight from Razorpay: captured, for THIS order, right
  //    amount, right currency.
  const payment = await fetchPayment(razorpayPaymentId);
  if (payment.status !== "captured") return { ok: false, status: 409, reason: "payment not captured" };
  if (payment.order_id !== razorpayOrderId) return { ok: false, status: 400, reason: "payment/order mismatch" };
  if (payment.currency !== "INR") return { ok: false, status: 400, reason: "currency mismatch" };
  if (payment.amount !== expectedPaise) return { ok: false, status: 400, reason: "amount mismatch" };

  // 3. Cross-check the Razorpay ORDER too (what we asked them to charge).
  const rzpOrder = await fetchRazorpayOrder(razorpayOrderId);
  if (rzpOrder.amount !== expectedPaise || rzpOrder.currency !== "INR") {
    return { ok: false, status: 400, reason: "razorpay order amount mismatch" };
  }

  // 4. Atomic, idempotent grant of the product stored on the order row. The
  //    payment's own creation time (from Razorpay, not from the client) lets the
  //    database tell a payment started inside the order's 30-minute life from
  //    one started after it expired; in that case the wallet is not debited and
  //    the order is flagged for admin review (see settle_razorpay_payment).
  const paidAt = Number.isSafeInteger(payment.created_at)
    ? new Date((payment.created_at as number) * 1000).toISOString()
    : null;
  const { error } = await supabaseAdmin.rpc("settle_razorpay_payment", {
    p_event_id: eventId,
    p_razorpay_order_id: razorpayOrderId,
    p_razorpay_payment_id: razorpayPaymentId,
    p_amount_paise: payment.amount,
    p_paid_at: paidAt,
  });
  if (error) {
    console.error("settle: grant failed", { code: error.code, message: error.message });
    return { ok: false, status: 500, reason: "grant failed" };
  }
  // Settlement may return void for a held or compensated capture. Success
  // requires the database's exact payment/order/purchase commitment proof.
  const { data: committed, error: commitmentError } = await supabaseAdmin.rpc(
    "razorpay_entitlement_committed", { p_order_id: order.id, p_payment_id: razorpayPaymentId }
  );
  if (commitmentError || committed !== true)
    return { ok: false, status: 503, reason: "entitlement not committed" };
  return { ok: true, orderId: order.id, amountRupees: Number(order.amount) };
}

export type RefundResult =
  | { ok: true; outcome: string }
  | { ok: false; status: number; reason: string };

// refund.processed webhook -> cancel the referrer's still-pending credit.
// The event payload is NOT trusted: we re-fetch the payment from Razorpay and
// only act on a FULL refund (amount_refunded >= amount). handle_payment_refund()
// is idempotent and only cancels a credit that is still inside its hold window.
export async function settleRefund(params: { razorpayPaymentId: string }): Promise<RefundResult> {
  const payment = await fetchPayment(params.razorpayPaymentId);
  const fullRefund = payment.refund_status === "full"
    || (Number.isSafeInteger(payment.amount_refunded) && (payment.amount_refunded as number) >= payment.amount);

  const { data, error } = await supabaseAdmin.rpc("handle_payment_refund", {
    p_razorpay_payment_id: params.razorpayPaymentId,
    p_full_refund: fullRefund,
  });
  if (error) {
    console.error("settle: refund handling failed", { code: error.code, message: error.message });
    return { ok: false, status: 500, reason: "refund handling failed" };
  }
  return { ok: true, outcome: String((data as { status?: string } | null)?.status ?? "unknown") };
}

// payment.dispute.* webhooks -> suspend / restore / reverse access.
// As with refunds the event payload is NOT trusted beyond the dispute id: the
// dispute is re-fetched from Razorpay and ITS status decides what happens.
//   open / under_review  -> "opened": access suspended while the dispute is open
//   won                  -> "won":    access restored
//   lost                 -> "lost":   money gone - reversed like a full refund
//                                     (the student's wallet amount is NOT given back)
//   closed               -> nothing automatic; logged for a manual decision
//                           (an open dispute stays suspended until someone decides).
export function disputeOutcome(status: string | undefined): "opened" | "won" | "lost" | null {
  if (status === "open" || status === "under_review") return "opened";
  if (status === "won") return "won";
  if (status === "lost") return "lost";
  return null;
}

export async function settleDispute(params: { disputeId: string }): Promise<RefundResult> {
  const dispute = await fetchDispute(params.disputeId);
  if (typeof dispute.payment_id !== "string" || !dispute.payment_id.startsWith("pay_")) {
    return { ok: false, status: 400, reason: "dispute has no payment" };
  }
  const outcome = disputeOutcome(dispute.status);
  if (!outcome) return { ok: true, outcome: `no_change_status_${String(dispute.status)}` };

  const { data, error } = await supabaseAdmin.rpc("handle_payment_dispute", {
    p_razorpay_payment_id: dispute.payment_id,
    p_outcome: outcome,
  });
  if (error) {
    console.error("settle: dispute handling failed", { code: error.code, message: error.message });
    return { ok: false, status: 500, reason: "dispute handling failed" };
  }
  return { ok: true, outcome: String((data as { status?: string } | null)?.status ?? "unknown") };
}

import { createClient } from "npm:@supabase/supabase-js@2";

// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are injected automatically
// into every Edge Function's environment - no need to set them manually
// via `supabase secrets set`. The service role key bypasses RLS, which
// this backend needs: it has to read/write orders, purchases, and
// payment_sessions across users, not just the calling user's own rows.
const supabaseUrl = Deno.env.get("SUPABASE_URL");
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!supabaseUrl || !serviceRoleKey) {
  throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY Edge Function environment variable.");
}

export const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey, {
  auth: { persistSession: false, autoRefreshToken: false },
});

// Verifies the bearer token from an incoming request's Authorization
// header and returns the authenticated user - the only thing that should
// ever identify who's paying. Never trust a uid passed as a plain body/
// query param, since that would let anyone buy a product "as" someone
// else.
export async function getUserFromAuthHeader(
  req: Request
): Promise<{ id: string; email?: string } | null> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "");
  if (!token) return null;

  const { data, error } = await supabaseAdmin.auth.getUser(token);
  if (error || !data.user) return null;

  return { id: data.user.id, email: data.user.email ?? undefined };
}

// The session's authentication assurance level ("aal1" = password only, "aal2" = MFA done).
// Only call this AFTER getUserFromAuthHeader() accepted the same token: it decodes the payload
// without re-verifying the signature.
export function aalFromAuthHeader(req: Request): string {
  const token = (req.headers.get("Authorization") ?? "").replace(/^Bearer\s+/i, "");
  try {
    const b64 = token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/");
    const claims = JSON.parse(atob(b64.padEnd(Math.ceil(b64.length / 4) * 4, "=")));
    return typeof claims.aal === "string" ? claims.aal : "";
  } catch {
    return "";
  }
}

// Talks to Razorpay's REST API directly over fetch (rather than importing
// the `razorpay` npm package) - keeps this dependency-free, which matters
// more in a Deno Edge Function than it did in the old Node/Firebase
// backend, where npm packages were the natural choice.

// Every call to Razorpay is bounded so a stalled connection fails fast (create-order answers 502,
// the webhook answers 5xx and Razorpay retries) instead of hanging until the platform kills the function.
const RAZORPAY_TIMEOUT_MS = 15_000;

function getKeys(): { keyId: string; keySecret: string } {
  const keyId = Deno.env.get("RAZORPAY_KEY_ID");
  const keySecret = Deno.env.get("RAZORPAY_KEY_SECRET");

  if (!keyId || !keySecret) {
    throw new Error(
      "Razorpay keys are not configured. Run:\n" +
        "  supabase secrets set RAZORPAY_KEY_ID=...\n" +
        "  supabase secrets set RAZORPAY_KEY_SECRET=..."
    );
  }

  // SAFETY CHECK: a previous incident had a real rzp_test_ key committed
  // to the repo (see SECURITY_NOTICE.md) and silently deployed as this
  // function's production secret - a console.warn() alone was too easy to
  // miss in logs nobody was watching, and every order kept getting created
  // as a Razorpay TEST order, which real UPI apps (PhonePe/GPay) do not
  // handle the same way as a live order (unreliable callbacks, different
  // auto-capture timing) - this was the actual root cause of intermittent
  // "payment succeeded but verification could not be confirmed" reports.
  //
  // Test mode is still fine for staging - but it now requires a conscious,
  // explicit opt-in secret (ALLOW_TEST_MODE=true) rather than being the
  // silent default the moment a test key ends up deployed. Without that
  // opt-in, a test key hard-fails every request instead of quietly
  // accepting real student payments against a test-mode order.
  if (keyId.startsWith("rzp_test_")) {
    const allowTestMode = Deno.env.get("ALLOW_TEST_MODE") === "true";
    if (!allowTestMode) {
      throw new Error(
        "Refusing to run with a rzp_test_ Razorpay key: ALLOW_TEST_MODE is not set to 'true'. " +
          "If this is staging and test mode is intentional, run " +
          "`supabase secrets set ALLOW_TEST_MODE=true`. " +
          "If this is production, you have the wrong key deployed - run " +
          "`supabase secrets set RAZORPAY_KEY_ID=rzp_live_...` and " +
          "`supabase secrets set RAZORPAY_KEY_SECRET=...` with your LIVE keys from " +
          "the Razorpay Dashboard (Settings -> API Keys, Live mode toggle)."
      );
    }
    console.warn(
      "[razorpay] RUNNING IN TEST MODE (RAZORPAY_KEY_ID starts with rzp_test_, " +
        "ALLOW_TEST_MODE=true). Real payments will NOT be processed."
    );
  }

  return { keyId, keySecret };
}

// Lets callers (e.g. `pay`) tell the client which mode it's in, so the app
// can visibly label the checkout screen "TEST MODE" instead of a student
// silently paying (or trying to pay) against a non-live order.
export function isLiveMode(): boolean {
  return getKeys().keyId.startsWith("rzp_live_");
}

export function getRazorpayKeyId(): string {
  return getKeys().keyId;
}

export async function createRazorpayOrder(params: {
  amountPaise: number;
  receipt: string;
  notes?: Record<string, string>;
}): Promise<{ id: string }> {
  const { keyId, keySecret } = getKeys();

  const res = await fetch("https://api.razorpay.com/v1/orders", {
    signal: AbortSignal.timeout(RAZORPAY_TIMEOUT_MS),
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Basic " + btoa(`${keyId}:${keySecret}`),
    },
    body: JSON.stringify({
      amount: params.amountPaise,
      currency: "INR",
      receipt: params.receipt,
      notes: params.notes ?? {},
    }),
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Razorpay order creation failed (${res.status}): ${body}`);
  }

  return (await res.json()) as { id: string };
}

// Server-to-server, authoritative check: asks Razorpay directly whether an
// order has a captured payment, using our own secret key. Used for
// "recovery" - e.g. when the app's WebView never got to relay Checkout's
// success callback (Android killed the WebView's renderer process while
// the app was backgrounded for a UPI app switch) even though the payment
// itself went through fine on Razorpay's side. Doesn't need a client-
// supplied signature at all, since this is us asking Razorpay ourselves.
export async function fetchCapturedPaymentForOrder(
  razorpayOrderId: string
): Promise<{ id: string; amount: number } | null> {
  const { keyId, keySecret } = getKeys();

  const res = await fetch(`https://api.razorpay.com/v1/orders/${razorpayOrderId}/payments`, {
    signal: AbortSignal.timeout(RAZORPAY_TIMEOUT_MS),
    headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Razorpay order-payments lookup failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as { items: { id: string; status: string; amount: number }[] };
  const captured = data.items.find((p) => p.status === "captured");
  return captured ? { id: captured.id, amount: captured.amount } : null;
}


export type RazorpayPayment = {
  id: string;
  order_id: string | null;
  status: string;
  amount: number;
  currency: string;
  captured?: boolean;
  created_at?: number; // epoch seconds: when the customer started this payment
  amount_refunded?: number;
  refund_status?: string | null; // "partial" | "full" | null
};

async function razorpayGet<T>(path: string): Promise<T> {
  const { keyId, keySecret } = getKeys();
  const res = await fetch(`https://api.razorpay.com/v1/${path}`, {
    signal: AbortSignal.timeout(RAZORPAY_TIMEOUT_MS),
    headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
  });
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Razorpay GET ${path.split("/")[0]} failed (${res.status}): ${body}`);
  }
  return (await res.json()) as T;
}

// Authoritative, server-to-server fetch of a single payment.
export function fetchPayment(paymentId: string): Promise<RazorpayPayment> {
  return razorpayGet<RazorpayPayment>(`payments/${encodeURIComponent(paymentId)}`);
}

export type RazorpayDispute = {
  id: string;
  payment_id: string;
  status: string; // "open" | "under_review" | "won" | "lost" | "closed"
  phase?: string; // "chargeback" | "fraud" | ...
  amount?: number;
};

// Authoritative, server-to-server fetch of a single dispute (chargeback).
export function fetchDispute(disputeId: string): Promise<RazorpayDispute> {
  return razorpayGet<RazorpayDispute>(`disputes/${encodeURIComponent(disputeId)}`);
}

export function fetchRazorpayOrder(
  razorpayOrderId: string
): Promise<{ id: string; amount: number; currency: string; status: string }> {
  return razorpayGet(`orders/${encodeURIComponent(razorpayOrderId)}`);
}

function hexToBytes(hex: string): Uint8Array | null {
  if (!/^[0-9a-f]{64}$/i.test(hex)) return null;
  const out = new Uint8Array(32);
  for (let i = 0; i < 32; i++) out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

// signature = HMAC_SHA256(razorpay_order_id + "|" + razorpay_payment_id, KEY_SECRET)
// Must match exactly what Checkout.js sends back. Compared in constant time
// over the decoded 32-byte digests (no early exit on the first differing byte).
export async function verifyPaymentSignature(params: {
  razorpayOrderId: string;
  razorpayPaymentId: string;
  razorpaySignature: string;
}): Promise<boolean> {
  const { keySecret } = getKeys();

  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(keySecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const expected = new Uint8Array(
    await crypto.subtle.sign("HMAC", key, enc.encode(`${params.razorpayOrderId}|${params.razorpayPaymentId}`))
  );
  const actual = hexToBytes(params.razorpaySignature);
  if (!actual) return false;

  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= expected[i] ^ actual[i];
  return diff === 0;
}
